\eqalignno{(\mu A)^{1/r}+(\mu B)^{1/r}
&=\sup\{(\mu K)^{1/r}+(\mu L)^{1/r}:
  K\subseteq A\text{ and }L\subseteq B\text{ are compact}\}\cr
\displaycause{134Fb}
&\le\sup\{\mu(K+L)^{1/r}:
  K\subseteq A\text{ and }L\subseteq B\text{ are compact}\}\cr
\displaycause{by (c)}
&\le\mu^*(A+B)^{1/r}.\cr}

